files = json.loads(files_json)

# Get git status for renames and modifications
status_output = subprocess.check_output(['git', 'diff', '--name-status', 'origin/master...trae/solo-agent-zsPw9E']).decode('utf-8')
status_map = {}
rename_map = {}
for line in status_output.strip().split('\n'):
    if not line: continue
    parts = line.split('\t')
    status = parts[0]
    if status.startswith('R'):
        old_path = parts[1]
        new_path = parts[2]
        status_map[new_path] = 'R'
        rename_map[new_path] = old_path
    elif status.startswith('A'):
        status_map[parts[1]] = 'A'
    elif status.startswith('D'):
        status_map[parts[1]] = 'D'
    elif status.startswith('M'):
        status_map[parts[1]] = 'M'

def get_change_desc(path):
    rel_path = path.replace('/workspace/', '')
    stat = status_map.get(rel_path, 'M')
    
    # Simple heuristics based on path and status
    if stat == 'D':
        return "- Removed file as part of the refactoring process"
    elif stat == 'R':
        old_path = rename_map.get(rel_path, "")
        return f"- Moved/Renamed file from `{old_path}` to adapt to the new DDD module structure"
    elif stat == 'A':
        if 'dto' in rel_path.lower() or 'mapper' in rel_path.lower():
            return "- Added new DTO or Mapper class to support data transfer in the new architecture"
        elif 'repository' in rel_path.lower() and 'impl' not in rel_path.lower():
            return "- Added new repository interface for domain-driven design persistence"
        elif 'repository/impl' in rel_path.lower() or 'persistence' in rel_path.lower():
            return "- Added JPA implementation for domain repository interfaces"
        elif 'entity' in rel_path.lower():
            return "- Added JPA entity class for database mapping"
        else:
            return "- Added new file to support the DDD refactoring"
    else: # M
        if 'pom.xml' in rel_path:
            return "- Updated Maven dependencies and module configurations"
        elif 'service' in rel_path.lower() or 'usecase' in rel_path.lower() or 'worker' in rel_path.lower():
            return "- Refactored service layer to align with the new DDD structure and repository interfaces"
        elif 'controller' in rel_path.lower() or 'api' in rel_path.lower():
            return "- Updated controller to use new service interfaces and DTOs"
        elif 'domain/model' in rel_path.lower():
            return "- Updated domain model to encapsulate business logic and attributes"
        else:
            return "- Modified file to integrate with the new DDD architecture"

print("This merge implements a comprehensive Domain-Driven Design (DDD) refactoring of the system architecture. It restructures the codebase into distinct layers (application, domain, infrastructure, interfaces) and renames modules like pipeline to batch-processing and splitter to text-processing for better domain alignment.")
print("| File | Changes |")
print("|------|---------|")
for f in files:
    path = f['path']
    rel_path = path.replace('/workspace/', '')
    desc = get_change_desc(path)
    print(f"| {rel_path} | {desc} |")
